def query_llama_server(prompt, max_tokens=1024):
    response = requests.post("http://localhost:8080/completion", json={
        "prompt": prompt,
        "stop": ["###"],
        "n_predict": max_tokens,
        "temperature": 0.2,
        "top_k": 40,
        "top_p": 0.95
    })
    return response.json()["content"].strip()
def estimate_tokens(llm, text):
    return len(llm.tokenize(text.encode("utf-8")))
def make_summary_prompt(code_chunk):
    return f"""### Instruction:
Read the following code carefully. Provide a concise but detailed summary that includes:
- The main purpose of the code
- Explanations of each function or class
- Any important design patterns, algorithms, or side effects

### Code:
{code_chunk}

### Response:
"""
### Response:
def summarize_worker(file_list, worker_id):
    failed = []

    for rel_path in tqdm(file_list, desc=f"Worker {worker_id} summarizing"):
        input_file = CHUNK_DIR / rel_path
        output_file = SUMMARY_DIR / rel_path.with_suffix(".summary.json")

        if output_file.exists():
            continue

        try:
            with open(input_file, 'r', encoding='utf-8') as f:
                chunks = [json.loads(line)["code"] for line in f]
        except Exception as e:
            print(f"⚠️ [Worker {worker_id}] Failed to read {rel_path}: {e}")
            failed.append(str(rel_path))
            continue

        combined_summary = ""

        for i, chunk in enumerate(chunks):
            prompt = make_summary_prompt(chunk)
            token_limit = 14000  # stay under 16k context with room for response

            if estimate_tokens(llm, prompt) > token_limit:
                print(f"⚠️ [Worker {worker_id}] Oversized chunk {i} in {rel_path}, summarizing in passes")
                lines = chunk.splitlines()
                subchunks = []
                current = []
                current_tokens = 0

                for line in lines:
                    line_tokens = estimate_tokens(llm, line)
                    if current_tokens + line_tokens > token_limit - 1000:
                        subchunks.append('\n'.join(current))
                        current = []
                        current_tokens = 0
                    current.append(line)
                    current_tokens = estimate_tokens(llm, '\n'.join(current))

                if current:
                    subchunks.append('\n'.join(current))

                partial_summaries = []
                for j, sub in enumerate(subchunks):
                    sub_prompt = make_summary_prompt(sub)
                    try:
                        summary = query_llama_server(sub_prompt, max_tokens=MAX_TOKENS)
                        partial_summaries.append(summary)
                    except Exception as e:
                        print(f"⚠️ [Worker {worker_id}] Error summarizing subchunk {j} of chunk {i} in {rel_path}: {e}")
                        failed.append(f"{rel_path} [subchunk {j} of chunk {i}]")

                # Final summary of summaries
                parts_text = "\n".join([f"[Part {j}]\n{summary}" for j, summary in enumerate(partial_summaries)])
                summary_prompt = f"""### Instruction:
This is a summary of a long code file broken into parts. Please summarize it as a whole.

### Parts:
{parts_text}

### Response:"""
                try:
                    final_summary = query_llama_server(summary_prompt, max_tokens=MAX_TOKENS)
                    combined_summary += f"\n[Chunk {i}]\n{final_summary}\n"
                except Exception as e:
                    print(f"⚠️ [Worker {worker_id}] Error summarizing combined parts of chunk {i} in {rel_path}: {e}")
                    failed.append(f"{rel_path} [combined parts of chunk {i}]")
            else:
                try:
                    summary = query_llama_server(prompt, max_tokens=MAX_TOKENS)
                    combined_summary += f"\n[Chunk {i}]\n{summary}\n"
                except Exception as e:
                    print(f"⚠️ [Worker {worker_id}] Error summarizing chunk {i} of {rel_path}: {e}")
                    failed.append(f"{rel_path} [chunk {i}]")

        output_file.parent.mkdir(parents=True, exist_ok=True)
        with open(output_file, 'w', encoding='utf-8') as f:
            json.dump({"file": str(rel_path), "summary": combined_summary.strip()}, f, indent=2)

        print(f"✅ [Worker {worker_id}] {rel_path} summarized")

    if failed:
        with open(FAILED_LOG, 'a', encoding='utf-8') as flog:
            for item in failed:
                flog.write(f"[Worker {worker_id}] {item}\n")

def split_workload()
all_jsonl = sorted(CHUNK_DIR.rglob("*.jsonl"))
    rel_paths = [f.relative_to(CHUNK_DIR) for f in all_jsonl][:10]  # <-- limit to first 10 files
    total = len(rel_paths)

    chunks = [rel_paths[i:i + CHUNKS_PER_WORKER] for i in range(0, total, CHUNKS_PER_WORKER)]
    return chunks


